mutation ClassroomStudentCreate($classroomId: String!, $students: [String!]!) {
  classroomStudentCreate(classroomId: $classroomId, students: $students) {
    id
    students {
      ...classroomStudentFragment
    }
  }
}

fragment classroomStudentFragment on ClassroomStudent {
  id
  invitationAccepted
  invitationCode
  name
  studentUserId
  educontUid
}

